"""Report and token usage database models."""

from typing import List, Optional, TYPE_CHECKING
from sqlalchemy import Float, ForeignKey, Integer, String, Text, JSON
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.database.base import Base, TimestampMixin, UUIDMixin

if TYPE_CHECKING:
    from app.models.research import ResearchProject
    from app.models.user import User


class Report(Base, UUIDMixin, TimestampMixin):
    """Final synthesis report generated by the Report Generation Agent."""
    __tablename__ = "reports"

    project_id: Mapped[str] = mapped_column(
        ForeignKey("research_projects.id", ondelete="CASCADE"), unique=True, index=True, nullable=False
    )
    title: Mapped[str] = mapped_column(String(500), nullable=False)
    executive_summary: Mapped[str] = mapped_column(Text, nullable=False)
    markdown_content: Mapped[str] = mapped_column(Text, nullable=False)
    pdf_path: Mapped[Optional[str]] = mapped_column(String(1000), nullable=True)
    sections: Mapped[List[dict]] = mapped_column(JSON, default=list, nullable=False)
    citation_count: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    source_count: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    unsupported_claims_count: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    verification_passed: Mapped[bool] = mapped_column(default=True, nullable=False)

    project: Mapped["ResearchProject"] = relationship("ResearchProject", back_populates="report")


class UsageRecord(Base, UUIDMixin, TimestampMixin):
    """Token and execution cost tracking record."""
    __tablename__ = "usage_records"

    user_id: Mapped[str] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"), index=True, nullable=False)
    project_id: Mapped[Optional[str]] = mapped_column(
        ForeignKey("research_projects.id", ondelete="CASCADE"), index=True, nullable=True
    )
    agent_name: Mapped[str] = mapped_column(String(100), index=True, nullable=False)
    model: Mapped[str] = mapped_column(String(100), nullable=False)
    prompt_tokens: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    completion_tokens: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    total_tokens: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    estimated_cost_usd: Mapped[float] = mapped_column(Float, default=0.0, nullable=False)

    user: Mapped["User"] = relationship("User", back_populates="usage_records")
    project: Mapped[Optional["ResearchProject"]] = relationship("ResearchProject", back_populates="usage_records")

